import {pathToFileURL} from 'node:url';
const offset=Number(process.env.MARKER_AUDIT_OFFSET??0);
let before,after;
if(offset%2){after=await import(pathToFileURL(process.env.MARKER_AUDIT_AFTER));before=await import(pathToFileURL(process.env.MARKER_AUDIT_BEFORE));}
else{before=await import(pathToFileURL(process.env.MARKER_AUDIT_BEFORE));after=await import(pathToFileURL(process.env.MARKER_AUDIT_AFTER));}
function isCurrent(path){return (Number(path[1])+offset)%4>=2;}
export function renderParticipant(data,path,...args){return (isCurrent(path)?after:before).renderParticipant(data,path.slice(2),...args);}
export function renderParticipantToSink(data,path,...args){return (isCurrent(path)?after:before).renderParticipantToSink(data,path.slice(2),...args);}

